INSERT INTO public.syllabus_trees (signature, "option", tree_version, subject, level, board, tree, coverage, model)
VALUES ('6f2b1d0f45dbeee0def0ae50c083b65984d34670b6c5b09cf84c79985e990050', '', 1, 'Mathematics', 'A-Level', 'AQA', $t12${"topics":[{"title":"A: Proof","subtopics":["Proof by deduction, proof by exhaustion, and disproof by counter-example","Proof by contradiction (including irrationality of √2 and infinitude of primes)"]},{"title":"B: Algebra and functions (1)","subtopics":["Laws of indices for all rational exponents","Surds: manipulation and rationalising the denominator","Quadratic functions and graphs; the discriminant; completing the square","Solving quadratic equations, including equations in a function of the unknown","Solving simultaneous equations (linear and quadratic) by elimination and substitution","Solving and interpreting linear and quadratic inequalities, graphically and algebraically","Manipulating polynomials: expanding, factorising, and the factor theorem","Simplifying rational expressions by factorising and algebraic division","Sketching graphs of functions, including the modulus function and y=a/x, y=a/x²","Using graphs to solve equations (intersection points) and proportional relationships","Composite functions","Inverse functions and their graphs"]},{"title":"B: Algebra and functions (2)","subtopics":["Graph transformations: y=af(x), y=f(x)+a, y=f(x+a), y=f(ax), and combinations","Decomposing rational functions into partial fractions","Using functions in modelling, including limitations and refinements"]},{"title":"C: Coordinate geometry in the (x, y) plane","subtopics":["Equation of a straight line; gradient conditions for parallel/perpendicular lines","Equation of a circle, including completing the square to find centre and radius","Circle geometry properties: angle in a semicircle, perpendicular from centre to chord, tangent-radius perpendicularity","Parametric equations of curves and conversion between Cartesian and parametric forms","Using parametric equations in modelling"]},{"title":"D: Sequences and series","subtopics":["Binomial expansion of (a+bx)^n for positive integer n","Binomial expansion for rational n and its use for approximation","Sequences: nth term formulae, recurrence relations, increasing/decreasing/periodic sequences","Sigma notation for sums of series","Arithmetic sequences and series","Geometric sequences and series: nth term and sum to n terms","Sum to infinity of a convergent geometric series","Using sequences and series in modelling"]},{"title":"E: Trigonometry (1)","subtopics":["Definitions of sine, cosine and tangent for all arguments","Sine rule, cosine rule, and area of a triangle","Radian measure, arc length, and area of a sector","Small angle approximations for sine, cosine and tangent","Graphs, symmetries and periodicity of sine, cosine and tangent","Exact values of sin, cos and tan for standard angles","Secant, cosecant and cotangent: definitions and relationships to sin/cos/tan","Inverse trigonometric functions (arcsin, arccos, arctan): graphs, domain and range","Trigonometric identities: tan≡sin/cos, sin²+cos²≡1, sec²≡1+tan², cosec²≡1+cot²","Addition (compound angle) formulae and double angle formulae, with geometric proofs","Expressing a cosθ + b sinθ as r cos(θ±α) or r sin(θ±α)","Solving trigonometric equations in a given interval"]},{"title":"E: Trigonometry (2)","subtopics":["Constructing proofs involving trigonometric functions and identities","Using trigonometric functions to solve problems in context (vectors, kinematics, forces)"]},{"title":"F: Exponentials and logarithms","subtopics":["The functions a^x and e^x and their graphs","Gradient of e^kx and why the exponential model is suitable in applications","log_a x as the inverse of a^x; the function ln x","Laws of logarithms","Solving equations of the form a^x = b","Using logarithmic graphs to estimate parameters in y=ax^n and y=kb^x","Exponential growth and decay modelling"]},{"title":"G: Differentiation","subtopics":["Derivative as gradient of the tangent / rate of change; sketching gradient functions; differentiation from first principles","Second derivatives; connection to convex/concave sections and points of inflection","Differentiating x^n and related sums, differences and constant multiples","Differentiating e^kx, a^kx, sin kx, cos kx, tan kx and ln x","Finding tangents and normals using differentiation","Stationary points: maxima, minima, points of inflection; increasing/decreasing functions","Product rule and quotient rule","Chain rule; connected rates of change; differentiating inverse functions","Implicit differentiation","Parametric differentiation (first derivative only)","Constructing simple differential equations in pure mathematics and in context"]},{"title":"H: Integration","subtopics":["The Fundamental Theorem of Calculus","Integrating x^n, e^kx, 1/x, sin kx, cos kx and related sums, differences and multiples","Evaluating definite integrals and finding the area under a curve","Finding the area between two curves","Integration as the limit of a sum","Integration by substitution","Integration by parts","Integrating using partial fractions (linear denominators)","Solving first order differential equations with separable variables","Interpreting the solution of a differential equation in context, including limitations (links to kinematics)"]},{"title":"I: Numerical methods","subtopics":["Locating roots of f(x)=0 by considering changes of sign","Simple iterative methods; cobweb and staircase diagrams","The Newton-Raphson method and other recurrence relations","Numerical integration using the trapezium rule","Using numerical methods to solve problems in context"]},{"title":"J: Vectors","subtopics":["Vectors in two and three dimensions","Magnitude and direction of a vector; converting between component and magnitude/direction form","Vector addition (diagrammatic and algebraic) and multiplication by scalars","Position vectors; calculating the distance between two points","Using vectors to solve problems in pure mathematics and in context (forces, kinematics)"]},{"title":"K: Statistical sampling","subtopics":["Population and sample; sampling techniques including simple random and opportunity sampling","Selecting or critiquing sampling techniques in the context of a statistical problem"]},{"title":"L: Data presentation and interpretation","subtopics":["Interpreting diagrams for single-variable data, including histograms","Scatter diagrams and regression lines for bivariate data; correlation","Measures of central tendency and variation, including standard deviation","Outliers, critiquing data presentation, and cleaning data"]},{"title":"M: Probability","subtopics":["Mutually exclusive and independent events","Conditional probability: tree diagrams, Venn diagrams, two-way tables, and the conditional probability formula","Modelling with probability, including critiquing assumptions"]},{"title":"N: Statistical distributions","subtopics":["Discrete probability distributions, including the binomial distribution as a model","The Normal distribution as a model; finding probabilities","Selecting an appropriate probability distribution for a context"]},{"title":"O: Statistical hypothesis testing","subtopics":["Language of statistical hypothesis testing (developed through a binomial model)","Hypothesis testing for correlation coefficients (interpretation only, no calculation)","Hypothesis test for the proportion in the binomial distribution","Hypothesis test for the mean of a Normal distribution with known variance"]},{"title":"P: Quantities and units in mechanics","subtopics":["Fundamental and derived quantities and units in mechanics (SI system)"]},{"title":"Q: Kinematics","subtopics":["Language of kinematics: position, displacement, distance, velocity, speed, acceleration","Kinematics graphs: displacement-time and velocity-time graphs","Constant acceleration (suvat) formulae for motion in a straight line, extended to 2D with vectors","Using calculus in kinematics for motion in a straight line, extended to 2D with vectors","Motion under gravity in a vertical plane using vectors; projectiles"]},{"title":"R: Forces and Newton's laws","subtopics":["The concept of a force; Newton's first law","Newton's second law for motion in a straight line, including resolved forces in 2D","Weight and motion under gravity; gravitational acceleration g","Newton's third law; equilibrium of a particle under coplanar forces","Pulleys and connected particles; resolving forces in 2D","Addition of forces (resultant forces); dynamics for motion in a plane","Friction: the F≤μR model, coefficient of friction, limiting friction and statics"]},{"title":"S: Moments","subtopics":["Moments in simple static contexts"]}],"coverage":{"verdict":"grounded","topics_grounded":21,"topics_total":21,"source_url":"https://www.aqa.org.uk/7357"}}$t12$::jsonb, $c13${"verdict":"grounded","topics_grounded":21,"topics_total":21,"source_url":"https://www.aqa.org.uk/7357"}$c13$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
