VALUES ('a86e1ebe59ccf822ac8fb12a2473f768fda5fac23e5a3326d1c86b08742a6014', '', 1, 'Further Mathematics', 'A-Level', 'AQA', $t14${"topics":[{"title":"Overarching themes","subtopics":["Mathematical argument, language and set theory","Functions, and critiquing mathematical arguments","Mathematical problem solving","Mathematical modelling"]},{"title":"A: Proof","subtopics":["Proof by induction — sums of series","Proof by induction — divisibility","Proof by induction — powers of matrices"]},{"title":"B: Complex numbers","subtopics":["Solving cubic and quartic equations with complex roots","Arithmetic of complex numbers in x + iy form","Complex conjugates and conjugate root pairs","Argand diagrams and modulus-argument form","Multiplying and dividing in modulus-argument form","Loci in the Argand diagram","De Moivre's theorem","Euler relation e^(iθ) and z = re^(iθ)","The n distinct nth roots of a complex number","Complex roots of unity in geometric problems"]},{"title":"C: Matrices","subtopics":["Matrix arithmetic: add, subtract, multiply, scalar multiply","Zero and identity matrices","Matrices as linear transformations in 2D and 3D","Invariant points and lines for a linear transformation","Determinants of 2x2 and 3x3 matrices","Singular/non-singular matrices and matrix inverses","Solving three linear simultaneous equations via the inverse matrix","Geometric interpretation of simultaneous equation solutions","Factorisation of determinants using row and column operations","Eigenvalues, eigenvectors and the characteristic equation","Diagonalisation of matrices"]},{"title":"D: Further algebra and functions (1)","subtopics":["Roots and coefficients of polynomial equations","Forming equations with transformed roots","Sums of integers, squares and cubes","Method of differences for summing series","Maclaurin series and the general term","Standard Maclaurin series","Evaluating limits with Maclaurin series or l'Hôpital's rule","Inequalities involving cubic and quartic polynomials","Solving algebraic-fraction inequalities algebraically","Modulus of functions and associated inequalities","Graphs of y = |f(x)| and y = 1/f(x)","Graphs of rational functions (linear over linear)"]},{"title":"D: Further algebra and functions (2)","subtopics":["Graphs of rational functions (quadratic over quadratic)","Range and stationary points of rational functions via quadratic theory","Sketching standard curves: parabolas, ellipses, hyperbolas","Transformations of curves"]},{"title":"E: Further calculus","subtopics":["Improper integrals","Volumes of revolution","Mean value of a function","Integration using partial fractions","Differentiating inverse trigonometric functions","Integrating using trigonometric substitutions","Arc length and surface area of revolution","Reduction formulae for integration","Limits of x^k e^(-x) and x^k ln x applied to improper integrals"]},{"title":"F: Further vectors","subtopics":["Vector and Cartesian equation of a line in 3D","Vector and Cartesian equation of a plane","Scalar product: angles between lines and planes","Checking perpendicularity using the scalar product","Vector product and its properties","Intersections and distances between lines and planes"]},{"title":"G: Polar coordinates","subtopics":["Polar and Cartesian coordinate conversion","Sketching polar curves","Area enclosed by a polar curve"]},{"title":"H: Hyperbolic functions","subtopics":["Definitions of hyperbolic functions","Differentiating and integrating hyperbolic functions","Inverse hyperbolic functions","Logarithmic forms of inverse hyperbolic functions","Integration using hyperbolic substitutions","Hyperbolic function identities","Constructing proofs involving hyperbolic functions"]},{"title":"I: Differential equations","subtopics":["Integrating factor method","General and particular solutions of differential equations","Differential equations in kinematics and modelling","Second order homogeneous differential equations (auxiliary equation)","Second order differential equations with f(x) (particular integral)","Discriminant cases of the auxiliary equation","Simple harmonic motion","Damped oscillations","Coupled first-order simultaneous differential equations","Hooke's law and formulating SHM equations","Models for damped motion"]},{"title":"J: Numerical methods","subtopics":["Mid-ordinate rule and Simpson's rule","Euler's step-by-step method","Improved Euler method"]}],"coverage":{"verdict":"grounded","topics_grounded":12,"topics_total":12,"source_url":"aqa.org.uk/7367"},"optionalUnits":["Optional application 1 – mechanics","Optional application 2 – statistics","Optional application 3 – discrete mathematics"]}$t14$::jsonb, $c15${"verdict":"grounded","topics_grounded":12,"topics_total":12,"source_url":"aqa.org.uk/7367"}$c15$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
