INSERT INTO public.syllabus_trees (signature, "option", tree_version, subject, level, board, tree, coverage, model)
VALUES ('a86e1ebe59ccf822ac8fb12a2473f768fda5fac23e5a3326d1c86b08742a6014', 'Optional application 2 – statistics', 1, 'Further Mathematics', 'A-Level', 'AQA', $t18${"topics":[{"title":"SA: Discrete random variables (DRVs) and expectation","subtopics":["DRVs given as a table or function","Evaluating probabilities for a DRV","Measures of average and spread for a DRV","Expectation formulae: E(X), E(X²), Var(X)","Expectation of linear functions of DRVs","Discrete uniform distribution","Proof of mean and variance of the discrete uniform distribution"]},{"title":"SB: Poisson distribution","subtopics":["Conditions for a Poisson distribution to model a situation","Poisson probability formula and calculator use","Mean and variance of a Poisson distribution","Distribution of the sum of independent Poisson distributions","Hypothesis test for a Poisson population mean"]},{"title":"SC: Type I and Type II errors","subtopics":["Type I and Type II errors; calculating P(Type I error)","Power of a test and calculating P(Type II error)"]},{"title":"SD: Continuous random variables (CRVs)","subtopics":["Probability density functions","Probability of an observation lying in an interval","Median and quartiles for a given pdf","Mean, variance and standard deviation for a given pdf","Expectation and variance of linear functions of CRVs","Cumulative distribution function","Rectangular (uniform) distribution","Sums of independent random variables: E(X+Y), Var(X+Y)"]},{"title":"SE: Chi squared tests for association","subtopics":["Construction of n x m contingency tables","Chi-squared test statistic and degrees of freedom","Convention that expected frequencies should exceed 5","Identifying sources of association in context","Yates' correction"]},{"title":"SF: Exponential distribution","subtopics":["Conditions, pdf and cdf for an exponential distribution","Calculating exponential probabilities","Proofs of mean, variance and standard deviation of the exponential distribution","Link between exponential distribution and intervals between Poisson events"]},{"title":"SG: Inference — one sample t-distribution","subtopics":["t-test for a normal mean with unknown variance"]},{"title":"SH: Confidence intervals","subtopics":["Confidence intervals for a normal mean with known variance","Confidence intervals from large samples, unknown variance","Making inferences from confidence intervals","Confidence intervals from small samples using the t-distribution"]}],"coverage":{"verdict":"grounded","topics_grounded":8,"topics_total":8,"source_url":"aqa.org.uk/7367"}}$t18$::jsonb, $c19${"verdict":"grounded","topics_grounded":8,"topics_total":8,"source_url":"aqa.org.uk/7367"}$c19$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
