INSERT INTO public.syllabus_trees (signature, "option", tree_version, subject, level, board, tree, coverage, model)
VALUES ('a86e1ebe59ccf822ac8fb12a2473f768fda5fac23e5a3326d1c86b08742a6014', 'Optional application 3 – discrete mathematics', 1, 'Further Mathematics', 'A-Level', 'AQA', $t20${"topics":[{"title":"DA: Graphs","subtopics":["Language of graphs","Eulerian, semi-Eulerian and Hamiltonian graphs","Euler's formula for connected planar graphs","Kuratowski's theorem for planarity","Complete graphs, bipartite graphs and adjacency matrices","Simple graphs, simple-connected graphs and trees","Isomorphism between graphs"]},{"title":"DB: Networks","subtopics":["Language of networks: node, arc, weight","Network optimisation using spanning trees","Route inspection problem","Upper and lower bounds for the travelling salesperson problem","Evaluating, modifying and refining network models"]},{"title":"DC: Network flows","subtopics":["Flow problems on a network of directed arcs","Value of a cut","Maximum flow-minimum cut theorem","Supersources and supersinks","Augmenting flows to determine maximum flow","Arcs with upper and lower capacities","Refining flow problems with restricted-capacity nodes"]},{"title":"DD: Linear programming","subtopics":["Formulating constrained optimisation problems","Solving constrained optimisation problems graphically","Simplex algorithm with slack variables","Interpreting a Simplex tableau"]},{"title":"DE: Critical path analysis","subtopics":["Precedence (activity) networks using activity-on-node","Earliest and latest start/finish times for an activity network","Critical activities, critical paths and float","Refining critical path models","Gantt (cascade) diagrams and resource histograms","Resource levelling and restricted-resource problems"]},{"title":"DF: Game theory for zero-sum games","subtopics":["Pay-off matrices","Play-safe strategies and the value of the game","Proving existence or non-existence of a stable solution","Dominated strategies","Optimal mixed strategies using graphical methods","Converting higher order games to linear programming problems"]},{"title":"DG: Binary operations","subtopics":["Binary operations, modular arithmetic and matrix multiplication","Commutativity of a binary operation","Associativity of a binary operation","Constructing a Cayley table","Existence of an identity element","Finding inverse elements","Language of groups: order, period, subgroup","Group axioms: closure, identity, inverses, associativity","Finite and infinite groups and subgroups","Lagrange's theorem","Generators of a group","Isomorphism between groups of finite order"]}],"coverage":{"verdict":"grounded","topics_grounded":7,"topics_total":7,"source_url":"aqa.org.uk/7367"}}$t20$::jsonb, $c21${"verdict":"grounded","topics_grounded":7,"topics_total":7,"source_url":"aqa.org.uk/7367"}$c21$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
