INSERT INTO public.syllabus_trees (signature, "option", tree_version, subject, level, board, tree, coverage, model)
VALUES ('f7c1a9a986adda80a51a19c2b2bcef3ef053ba983195c44ce9c61ee722c6fd57', '', 1, 'Mathematics', 'A-Level', 'Edexcel', $t22${"topics":[{"title":"Proof","subtopics":["Proof by deduction","Proof by exhaustion","Disproof by counter example","Proof by contradiction (including irrationality of √2 and infinity of primes)"]},{"title":"Algebra and functions (1)","subtopics":["Laws of indices for all rational exponents","Surds: manipulation and rationalising the denominator","Quadratic functions and their graphs; the discriminant","Completing the square and solving quadratic equations, including in a function of the unknown","Solving simultaneous equations (one linear, one quadratic) by elimination and substitution","Solving and representing linear and quadratic inequalities, including with brackets/fractions and set notation","Manipulating polynomials: expanding, factorising and the factor theorem","Simplifying rational expressions by factorising and algebraic division","Sketching cubic and quartic graphs, and the modulus of a linear function","Reciprocal graphs y=a/x and y=a/x², their asymptotes, and interpreting algebraic solutions graphically","Proportional relationships and their graphs","Composite functions; inverse functions and their graphs"]},{"title":"Algebra and functions (2)","subtopics":["Transformations of the graph of y=f(x): af(x), f(x)+a, f(x+a), f(ax) and combinations","Decomposing rational functions into partial fractions","Using functions in modelling, including limitations and refinements"]},{"title":"Coordinate geometry in the (x, y) plane","subtopics":["Equation of a straight line; parallel/perpendicular gradient conditions; straight-line models","Coordinate geometry of the circle, including circle properties and tangents","Parametric equations of curves and conversion between Cartesian and parametric forms","Using parametric equations in modelling"]},{"title":"Sequences and series","subtopics":["Binomial expansion of (a+bx)^n for positive integer n","Binomial expansion extended to any rational n, including the condition for validity","Sequences defined by a formula for the nth term or by a recurrence relation; increasing, decreasing and periodic sequences","Sigma notation for sums of series","Arithmetic sequences and series, including the nth term and sum to n terms","Geometric sequences and series, including sum to infinity of a convergent series","Using sequences and series in modelling"]},{"title":"Trigonometry","subtopics":["Sine, cosine and tangent for all arguments; the sine and cosine rules; area of a triangle","Radian measure: arc length and area of a sector","Small angle approximations for sine, cosine and tangent","Sine, cosine and tangent graphs: symmetries, periodicity and exact values","Secant, cosecant and cotangent; arcsin, arccos and arctan, their graphs, ranges and domains","tanθ = sinθ/cosθ and sin²θ + cos²θ = 1 and related identities (sec²θ, cosec²θ)","Double angle formulae for sin(A±B), cos(A±B) and tan(A±B)","Expressing a cosθ + b sinθ in the form R cos(θ±α)","Solving trigonometric equations in a given interval, including quadratics in sin/cos/tan","Constructing proofs involving trigonometric functions and identities","Using trigonometric functions to solve problems in context (vectors, kinematics, forces)"]},{"title":"Exponentials and logarithms","subtopics":["The function a^x and its graph; the function e^x and its graph","Gradient of e^kx and why the exponential model is suitable in applications","Definition of log_a x as the inverse of a^x; the function ln x as the inverse of e^x","Laws of logarithms","Solving equations of the form a^x = b","Using logarithmic graphs to estimate parameters in relationships y=ax^n and y=kb^x","Exponential growth and decay, and modelling with limitations/refinements"]},{"title":"Differentiation","subtopics":["The derivative as gradient of the tangent and rate of change; sketching gradient functions; differentiation from first principles","The second derivative as rate of change of gradient; convex/concave sections and points of inflection","Differentiating x^n for rational n and related sums, differences and constant multiples","Differentiating e^kx, a^kx, sin kx, cos kx, tan kx and ln x","Applying differentiation to find tangents, normals, maxima/minima, stationary points and identify increasing/decreasing functions","Product rule, quotient rule and chain rule, including connected rates of change and inverse functions","Differentiating implicitly and parametrically defined functions (first derivative)","Constructing simple differential equations in pure mathematics and in context"]},{"title":"Integration","subtopics":["Integration as the reverse of differentiation; the Fundamental Theorem of Calculus","Integrating x^n (n≠−1) and related sums, differences and constant multiples","Integrating e^kx, 1/x, sin kx, cos kx and related sums and differences","Evaluating definite integrals; area under a curve and area between two curves","Integration as the limit of a sum","Integration by substitution","Integration by parts","Integration using partial fractions (linear denominators)","Solving simple first order separable differential equations, including finding particular solutions","Interpreting the solution of a differential equation in context, including limitations and links to kinematics"]},{"title":"Numerical methods","subtopics":["Locating roots of f(x)=0 by sign change, and understanding how change-of-sign methods can fail","Solving equations approximately using simple iterative methods; cobweb and staircase diagrams","Solving equations using the Newton-Raphson method and understanding how it can fail","Numerical integration using the trapezium rule, including over/under-estimate limits","Using numerical methods to solve problems in context"]},{"title":"Vectors","subtopics":["Using vectors in two and three dimensions, including i, j, k notation","Calculating the magnitude and direction of a vector; converting between component and magnitude/direction form","Adding vectors diagrammatically; vector addition and scalar multiplication and their geometric interpretation","Position vectors; calculating the distance between two points represented by position vectors","Using vectors to solve problems in pure mathematics and in context, including forces"]},{"title":"Statistical sampling","subtopics":["Population and sample; using samples to make informal inferences about the population","Sampling techniques (simple random, stratified, systematic, quota and opportunity sampling) and selecting/critiquing them in context"]},{"title":"Data presentation and interpretation","subtopics":["Interpreting diagrams for single-variable data: histograms, frequency polygons, box plots and cumulative frequency diagrams","Interpreting scatter diagrams and regression lines for bivariate data; correlation","Interpreting measures of central tendency and variation, including standard deviation, from raw data or summary statistics","Recognising outliers; critiquing data presentation techniques; cleaning data (missing data, errors, outliers)"]},{"title":"Probability","subtopics":["Mutually exclusive and independent events; linking discrete and continuous distributions","Conditional probability, including tree diagrams, Venn diagrams, two-way tables and the conditional probability formula","Modelling with probability, including critiquing assumptions"]},{"title":"Statistical distributions","subtopics":["Discrete probability distributions, including the binomial distribution as a model","The Normal distribution as a model; finding probabilities using it","Selecting an appropriate probability distribution for a context, with reasoning"]},{"title":"Statistical hypothesis testing","subtopics":["Language of statistical hypothesis testing developed through a binomial model, and interpreting correlation coefficients via p-value or critical value","Conducting a hypothesis test for the proportion in the binomial distribution and interpreting results in context","Conducting a hypothesis test for the mean of a Normal distribution with known/given/assumed variance"]},{"title":"Quantities and units in mechanics","subtopics":["Fundamental and derived S.I. quantities and units in mechanics (length, time, mass, velocity, acceleration, force, weight, moment)"]},{"title":"Kinematics","subtopics":["The language of kinematics: position, displacement, distance travelled, velocity, speed, acceleration","Kinematics graphs for motion in a straight line: displacement-time and velocity-time graphs and interpreting gradient/area","Constant acceleration (suvat) formulae for straight-line motion, extended to 2 dimensions using vectors","Using calculus in kinematics for straight-line motion, extended to 2 dimensions using vectors","Modelling motion under gravity in a vertical plane using vectors; projectiles"]},{"title":"Forces and Newton's laws","subtopics":["The concept of a force; Newton's first law","Newton's second law for motion in a straight line, including resolving forces in two dimensions","Weight and motion in a straight line under gravity; gravitational acceleration g and its accuracy","Newton's third law; equilibrium of a particle; problems involving smooth pulleys and connected particles","Addition of forces; resultant forces; dynamics for motion in a plane","The F ≤ μR model for friction, coefficient of friction, motion on a rough surface, limiting friction and statics"]},{"title":"Moments","subtopics":["Understanding and using moments in simple static contexts, including equilibrium of rigid bodies"]}],"coverage":{"verdict":"grounded","topics_grounded":20,"topics_total":20,"source_url":"https://qualifications.pearson.com"}}$t22$::jsonb, $c23${"verdict":"grounded","topics_grounded":20,"topics_total":20,"source_url":"https://qualifications.pearson.com"}$c23$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
