INSERT INTO public.syllabus_trees (signature, "option", tree_version, subject, level, board, tree, coverage, model)
VALUES ('1cf619fb6f03045234d5d321b648f4556a8e3670a85f26e33b69fe0ddb08853f', '', 1, 'Physics', 'A-Level', 'Edexcel', $t24${"topics":[{"title":"Topic 1: Working as a Physicist","subtopics":["Quantities, units, estimation, and the scientific process"]},{"title":"Topic 2: Mechanics","subtopics":["SUVAT equations and motion graphs","Vectors, resolving forces, and projectile motion","Newton's second law, free-body diagrams, weight and free fall (CORE PRACTICAL 1)","Newton's third law and conservation of linear momentum","Moments, centre of gravity and equilibrium of extended bodies","Work, energy, power and efficiency"]},{"title":"Topic 3: Electric Circuits","subtopics":["Current, charge and Ohm's law","Charge/energy conservation in circuits: series and parallel resistance","Electrical power and current-potential difference characteristics","Resistivity (CORE PRACTICAL 2) and the microscopic current equation","Potential dividers, including variable resistors, thermistors and LDRs","E.m.f. and internal resistance (CORE PRACTICAL 3)","Microscopic models of resistance: temperature and light dependence"]},{"title":"Topic 4: Materials","subtopics":["Density, upthrust and Stokes' law for viscous drag","CORE PRACTICAL 4: Viscosity of a liquid by falling-ball method","Hooke's law, stress, strain and the Young modulus","CORE PRACTICAL 5: Determine the Young modulus of a material","Elastic strain energy from force-extension graphs"]},{"title":"Topic 5: Waves and Particle Nature of Light","subtopics":["Wave quantities, transverse and longitudinal waves","CORE PRACTICAL 6: Speed of sound in air using oscilloscope, signal generator, speaker and microphone","Superposition, coherence, path difference and standing waves","CORE PRACTICAL 7: Frequency of a vibrating string or wire","Intensity of radiation, refraction and critical angle","Lenses: ray diagrams, power, thin lens equation and magnification","Polarisation and diffraction (single-slit and diffraction grating)","CORE PRACTICAL 8: Wavelength of light from a laser using a diffraction grating","Wave-particle duality: electron diffraction and the de Broglie equation","Wave transmission, pulse-echo technique and the photon model of EM radiation","The photoelectric effect: threshold frequency, work function and the electronvolt","Atomic line spectra and discrete energy levels"]},{"title":"Topic 6: Further Mechanics","subtopics":["Impulse and force-momentum relationship (CORE PRACTICAL 9)","2D momentum conservation, elastic/inelastic collisions (CORE PRACTICAL 10)","Circular motion: angular velocity, centripetal acceleration and force"]},{"title":"Topic 7: Electric and Magnetic Fields","subtopics":["Electric field strength and Coulomb's law","Electric potential, uniform and radial fields","Capacitance and energy stored in a capacitor","CORE PRACTICAL 11: Charge/discharge of a capacitor through a resistor and the time constant","Magnetic flux density and forces on moving charges/current-carrying conductors","Electromagnetic induction: Faraday's law and Lenz's law","Alternating current: peak and root-mean-square values"]},{"title":"Topic 8: Nuclear and Particle Physics","subtopics":["Nuclear model of the atom and alpha particle scattering","Thermionic emission and particle accelerators/detectors","Conservation of charge, energy and momentum; mass-energy equivalence in particle interactions","The standard quark-lepton model","Conservation laws (charge, baryon, lepton number) and particle equations"]},{"title":"Topic 9: Thermodynamics","subtopics":["Specific heat capacity and specific latent heat (CORE PRACTICALS 12, 13)","Internal energy, absolute zero and the kinetic theory model","CORE PRACTICAL 14: Pressure-volume relationship for a gas and mean molecular kinetic energy","Black body radiation: Stefan-Boltzmann and Wien's laws"]},{"title":"Topic 10: Space","subtopics":["Intensity, luminosity and astronomical distance measurement","Hertzsprung-Russell diagram and stellar life cycles","Doppler effect, redshift and Hubble's law"]},{"title":"Topic 11: Nuclear Radiation","subtopics":["Nuclear binding energy, mass deficit, fusion and fission","Background radiation and properties of alpha, beta and gamma radiation","CORE PRACTICAL 15: Absorption of gamma radiation by lead","Radioactive decay: half-life and exponential decay equations"]},{"title":"Topic 12: Gravitational Fields","subtopics":["Gravitational field strength and Newton's law of gravitation","Gravitational potential, field comparison, and orbital motion"]},{"title":"Topic 13: Oscillations","subtopics":["Simple harmonic motion: defining equation and standard SHM equations","Displacement-time and velocity-time graphs for oscillators","Resonance, damping and CORE PRACTICAL 16 (resonant frequency to find unknown mass)"]}],"coverage":{"verdict":"grounded","topics_grounded":13,"topics_total":13,"source_url":"https://qualifications.pearson.com/content/dam/pdf/A%20Level/Physics/2015/Specification%20and%20sample%20assessments/pearsonedexcel-alevel-physics-spec.pdf"}}$t24$::jsonb, $c25${"verdict":"grounded","topics_grounded":13,"topics_total":13,"source_url":"https://qualifications.pearson.com/content/dam/pdf/A%20Level/Physics/2015/Specification%20and%20sample%20assessments/pearsonedexcel-alevel-physics-spec.pdf"}$c25$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
