INSERT INTO public.syllabus_trees (signature, "option", tree_version, subject, level, board, tree, coverage, model)
VALUES ('f72699cac9c0be5695b8b31003f75069de5f4e785f298408ac105f927b3d204d', '', 1, 'Further Mathematics', 'A-Level', 'Edexcel', $t26${"topics":[{"title":"Proof","subtopics":["Proof by mathematical induction (series, divisibility, matrix products)"]},{"title":"Complex numbers","subtopics":["Solving cubic and quartic equations with complex roots","Complex number arithmetic: add, subtract, multiply, divide (x+iy form)","Complex conjugates and conjugate root pairs","Argand diagrams","Cartesian to modulus-argument form conversion","Multiplying and dividing complex numbers in modulus-argument form","Loci and regions in the Argand diagram","De Moivre's theorem: multiple angle formulae and sums of series","Euler's relation e^(i*theta) and exponential form z = re^(i*theta)","The n distinct nth roots of a complex number","Using complex roots of unity to solve geometric problems"]},{"title":"Matrices","subtopics":["Adding, subtracting, multiplying conformable matrices; scalar multiplication","Zero and identity matrices","Matrices representing linear transformations in 2-D and 3-D","Invariant points and invariant lines of a linear transformation","Determinants of 2x2 and 3x3 matrices as scale factors","Singular/non-singular matrices; calculating matrix inverses","Solving three linear simultaneous equations using the inverse matrix","Geometric interpretation of solutions of three simultaneous linear equations"]},{"title":"Further algebra and functions","subtopics":["Relationship between roots and coefficients of polynomial equations","Forming a polynomial equation with transformed roots","Sums of integers, squares and cubes; summing other series","Method of differences for summation of series (with partial fractions)","Maclaurin series of a function, including the general term","Standard Maclaurin series (e^x, ln(1+x), sinx, cosx, (1+x)^n)"]},{"title":"Further calculus","subtopics":["Volumes of revolution about x- and y-axes","Improper integrals","Mean value of a function","Integration using partial fractions","Differentiating inverse trigonometric functions","Integrating functions leading to inverse trig substitutions"]},{"title":"Further vectors","subtopics":["Vector and Cartesian equation of a straight line in 3-D","Vector and Cartesian equation of a plane","Scalar product: equation of a plane, angles between lines/planes","Checking vectors are perpendicular using the scalar product","Intersection of a line and a plane; perpendicular distances"]},{"title":"Polar coordinates","subtopics":["Polar coordinates and conversion to/from Cartesian","Sketching polar curves r = f(theta)","Area enclosed by a polar curve"]},{"title":"Hyperbolic functions","subtopics":["Definitions, domains and ranges of sinh x, cosh x, tanh x","Differentiating and integrating hyperbolic functions","Inverse hyperbolic functions: definitions, domains, ranges","Logarithmic forms of inverse hyperbolic functions","Integrating functions using inverse hyperbolic substitutions"]},{"title":"Differential equations","subtopics":["First order linear differential equations via integrating factor","General and particular solutions of differential equations","Differential equations in modelling (kinematics and other contexts)","Second order homogeneous differential equations via auxiliary equation","Second order non-homogeneous differential equations (particular integral + complementary function)","Discriminant of the auxiliary equation and the form of solution","Simple harmonic motion differential equation","Modelling damped oscillations with second order differential equations","Coupled first order simultaneous differential equations (e.g. predator-prey models)"]}],"coverage":{"verdict":"grounded","topics_grounded":9,"topics_total":9,"source_url":"https://qualifications.pearson.com"},"optionalUnits":["Further Pure Mathematics 1","Further Statistics 1","Further Mechanics 1","Decision Mathematics 1","Further Pure Mathematics 2","Further Statistics 2","Further Mechanics 2","Decision Mathematics 2"]}$t26$::jsonb, $c27${"verdict":"grounded","topics_grounded":9,"topics_total":9,"source_url":"https://qualifications.pearson.com"}$c27$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
