INSERT INTO public.syllabus_trees (signature, "option", tree_version, subject, level, board, tree, coverage, model)
VALUES ('f72699cac9c0be5695b8b31003f75069de5f4e785f298408ac105f927b3d204d', 'Further Pure Mathematics 1', 1, 'Further Mathematics', 'A-Level', 'Edexcel', $t28${"topics":[{"title":"Further Trigonometry","subtopics":["The t-formulae (tan half-angle substitution)","Applying t-formulae to trigonometric identities","Applying t-formulae to solve trigonometric equations"]},{"title":"Further calculus","subtopics":["Derivation and use of Taylor series","Using series expansions to find limits","Leibnitz's theorem for differentiating products","L'Hospital's rule for indeterminate limits","The Weierstrass substitution for integration"]},{"title":"Further differential equations","subtopics":["Taylor series method for series solution of differential equations","Differential equations reducible by a given substitution"]},{"title":"Coordinate systems","subtopics":["Cartesian and parametric equations of parabola, ellipse, hyperbola","Focus-directrix properties and eccentricity of conics","Tangents and normals to parabola, ellipse, hyperbola","Loci problems with conics"]},{"title":"Further vectors","subtopics":["The vector product a x b","The scalar triple product a.(b x c)","Vector applications to 3-D geometry (points, lines, planes)"]},{"title":"Further numerical methods","subtopics":["Numerical solution of first and second order differential equations","Simpson's rule"]},{"title":"Inequalities","subtopics":["Manipulating and solving algebraic inequalities and inequations (incl. modulus)"]}],"coverage":{"verdict":"grounded","topics_grounded":7,"topics_total":7,"source_url":"https://qualifications.pearson.com"}}$t28$::jsonb, $c29${"verdict":"grounded","topics_grounded":7,"topics_total":7,"source_url":"https://qualifications.pearson.com"}$c29$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
