INSERT INTO public.syllabus_trees (signature, "option", tree_version, subject, level, board, tree, coverage, model)
VALUES ('f72699cac9c0be5695b8b31003f75069de5f4e785f298408ac105f927b3d204d', 'Further Statistics 1', 1, 'Further Mathematics', 'A-Level', 'Edexcel', $t30${"topics":[{"title":"Discrete probability distributions","subtopics":["Mean and variance of discrete probability distributions; E(g(X))"]},{"title":"Poisson & binomial distributions","subtopics":["The Poisson distribution and its additive property","Mean and variance of binomial and Poisson distributions","Poisson approximation to the binomial distribution"]},{"title":"Geometric and negative binomial distributions","subtopics":["Geometric and negative binomial distributions","Mean and variance of a geometric distribution","Mean and variance of a negative binomial distribution"]},{"title":"Hypothesis Testing","subtopics":["Hypothesis test for the mean of a Poisson distribution","Hypothesis test for the parameter p of a geometric distribution"]},{"title":"Central Limit Theorem","subtopics":["Applications of the Central Limit Theorem to other distributions"]},{"title":"Chi Squared Tests","subtopics":["Goodness of fit tests and contingency tables (chi-squared statistic)"]},{"title":"Probability generating functions","subtopics":["Definitions, derivations and applications of probability generating functions","Using PGFs to find the mean and variance","PGF of the sum of independent random variables"]},{"title":"Quality of tests","subtopics":["Type I and Type II errors; size and power of a test"]}],"coverage":{"verdict":"grounded","topics_grounded":8,"topics_total":8,"source_url":"https://qualifications.pearson.com"}}$t30$::jsonb, $c31${"verdict":"grounded","topics_grounded":8,"topics_total":8,"source_url":"https://qualifications.pearson.com"}$c31$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
