VALUES ('f72699cac9c0be5695b8b31003f75069de5f4e785f298408ac105f927b3d204d', 'Further Mechanics 1', 1, 'Further Mathematics', 'A-Level', 'Edexcel', $t32${"topics":[{"title":"Momentum and impulse","subtopics":["Momentum, impulse and conservation of momentum for direct collisions","Momentum as a vector; impulse-momentum principle in vector form"]},{"title":"Work, energy and power","subtopics":["Kinetic/potential energy, work-energy principle, conservation of mechanical energy"]},{"title":"Elastic strings and springs and elastic energy","subtopics":["Elastic strings and springs; Hooke's law","Energy stored in an elastic string or spring"]},{"title":"Elastic collisions in one dimension","subtopics":["Direct impact of elastic spheres; Newton's law of restitution","Successive direct impacts of spheres"]},{"title":"Elastic collisions in two dimensions","subtopics":["Oblique impact of smooth elastic spheres and a fixed surface","Successive oblique impacts of a sphere with plane surfaces"]}],"coverage":{"verdict":"grounded","topics_grounded":5,"topics_total":5,"source_url":"https://qualifications.pearson.com"}}$t32$::jsonb, $c33${"verdict":"grounded","topics_grounded":5,"topics_total":5,"source_url":"https://qualifications.pearson.com"}$c33$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
