INSERT INTO public.syllabus_trees (signature, "option", tree_version, subject, level, board, tree, coverage, model)
VALUES ('f72699cac9c0be5695b8b31003f75069de5f4e785f298408ac105f927b3d204d', 'Decision Mathematics 1', 1, 'Further Mathematics', 'A-Level', 'Edexcel', $t34${"topics":[{"title":"Algorithms and graph theory","subtopics":["General ideas of algorithms; implementation from flowchart or text","Bin packing, bubble sort and quick sort","Order of nodes; Eulerian, semi-Eulerian graphs","The planarity algorithm for planar graphs"]},{"title":"Algorithms on graphs","subtopics":["Minimum spanning tree: Prim's and Kruskal's algorithms","Dijkstra's and Floyd's algorithms for shortest path"]},{"title":"Algorithms on graphs II","subtopics":["Route inspection algorithm (Chinese postman problem)","Travelling salesman problem: upper/lower bounds and nearest neighbour algorithm"]},{"title":"Critical path analysis","subtopics":["Modelling a project by an activity network from a precedence table","Completing a precedence table for a given activity network","Critical path algorithm: earliest/latest event, start and finish times","Total float of an activity; Gantt (cascade) charts","Resource histograms based on worker requirements","Scheduling activities using the least number of workers"]},{"title":"Linear programming","subtopics":["Formulating problems as linear programs (slack, surplus, artificial variables)","Graphical solution of two-variable linear programs","The Simplex algorithm and tableau for <= constraints","Two-stage Simplex and big-M methods for mixed constraints"]}],"coverage":{"verdict":"grounded","topics_grounded":5,"topics_total":5,"source_url":"https://qualifications.pearson.com"}}$t34$::jsonb, $c35${"verdict":"grounded","topics_grounded":5,"topics_total":5,"source_url":"https://qualifications.pearson.com"}$c35$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
