INSERT INTO public.syllabus_trees (signature, "option", tree_version, subject, level, board, tree, coverage, model)
VALUES ('f72699cac9c0be5695b8b31003f75069de5f4e785f298408ac105f927b3d204d', 'Further Pure Mathematics 2', 1, 'Further Mathematics', 'A-Level', 'Edexcel', $t36${"topics":[{"title":"Groups","subtopics":["The axioms of a group","Examples of groups, Cayley tables, cyclic groups","Order of a group and of an element; subgroups","Lagrange's theorem","Isomorphism between groups"]},{"title":"Further calculus","subtopics":["Further integration by reduction formulae","Arc length and area of a surface of revolution"]},{"title":"Further matrix algebra","subtopics":["Eigenvalues and eigenvectors of 2x2 and 3x3 matrices","Reduction of matrices to diagonal form","The Cayley-Hamilton theorem"]},{"title":"Further complex numbers","subtopics":["Further loci and regions in the Argand diagram","Elementary transformations from the z-plane to the w-plane"]},{"title":"Number theory","subtopics":["The division theorem, Euclidean algorithm and congruences","Bezout's identity","Modular arithmetic and congruences","Fermat's Little Theorem","Divisibility tests (2,3,4,5,6,9,10,11)","Solution of congruence equations","Combinatorics: counting problems, permutations and combinations"]},{"title":"Further sequences and series","subtopics":["First and second order recurrence relations","Solving recurrence relations to obtain closed forms","Proof by induction of closed forms of recurrence relations"]}],"coverage":{"verdict":"grounded","topics_grounded":6,"topics_total":6,"source_url":"https://qualifications.pearson.com"}}$t36$::jsonb, $c37${"verdict":"grounded","topics_grounded":6,"topics_total":6,"source_url":"https://qualifications.pearson.com"}$c37$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
