INSERT INTO public.syllabus_trees (signature, "option", tree_version, subject, level, board, tree, coverage, model)
VALUES ('f72699cac9c0be5695b8b31003f75069de5f4e785f298408ac105f927b3d204d', 'Further Statistics 2', 1, 'Further Mathematics', 'A-Level', 'Edexcel', $t38${"topics":[{"title":"Linear Regression","subtopics":["Least squares linear regression","Residuals and the residual sum of squares (RSS)"]},{"title":"Continuous probability distributions","subtopics":["Continuous random variables: probability density and cumulative distribution functions","Relationship between pdf and cdf","Mean, variance, mode, median, percentiles and skewness of continuous random variables","The continuous uniform (rectangular) distribution"]},{"title":"Correlation","subtopics":["Product moment correlation coefficient","Spearman's rank correlation coefficient","Hypothesis testing that a correlation is zero"]},{"title":"Combinations of random variables","subtopics":["Distribution of linear combinations of independent Normal random variables"]},{"title":"Estimation, confidence intervals and tests using a normal distribution","subtopics":["Standard error, estimators, bias, quality of estimators","Concept of a confidence interval","Confidence limits for a Normal mean, variance known","Hypothesis test for difference between two Normal means, variances known","Large-sample results extending to unknown population variances (via CLT)"]},{"title":"Other Hypothesis Tests and confidence intervals","subtopics":["Hypothesis test and confidence interval for the variance of a Normal distribution","Hypothesis test that two samples come from Normal populations with equal variances"]},{"title":"Confidence intervals and tests using the t-distribution","subtopics":["Hypothesis test and CI for the mean of a Normal distribution, unknown variance","Paired t-test","Hypothesis test and CI for the difference between two means, equal unknown variances"]}],"coverage":{"verdict":"grounded","topics_grounded":7,"topics_total":7,"source_url":"https://qualifications.pearson.com"}}$t38$::jsonb, $c39${"verdict":"grounded","topics_grounded":7,"topics_total":7,"source_url":"https://qualifications.pearson.com"}$c39$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
