VALUES ('f72699cac9c0be5695b8b31003f75069de5f4e785f298408ac105f927b3d204d', 'Further Mechanics 2', 1, 'Further Mathematics', 'A-Level', 'Edexcel', $t40${"topics":[{"title":"Motion in a circle","subtopics":["Angular speed; uniform motion in a horizontal circle; radial acceleration","Motion of a particle in a vertical circle"]},{"title":"Centres of mass of plane figures","subtopics":["Moment of a force; centre of mass of a discrete mass distribution","Centre of mass of uniform plane figures and frameworks"]},{"title":"Further centres of mass","subtopics":["Centre of mass of uniform and non-uniform rigid bodies","Equilibrium of rigid bodies under coplanar forces","Toppling and sliding of a rigid body on a rough plane"]},{"title":"Further dynamics","subtopics":["Newton's laws of motion for a variable applied force (1-D)","Simple harmonic motion: oscillations of a particle on elastic strings/springs"]},{"title":"Further kinematics","subtopics":["Kinematics with acceleration as a function of displacement, time or velocity"]}],"coverage":{"verdict":"grounded","topics_grounded":5,"topics_total":5,"source_url":"https://qualifications.pearson.com"}}$t40$::jsonb, $c41${"verdict":"grounded","topics_grounded":5,"topics_total":5,"source_url":"https://qualifications.pearson.com"}$c41$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
