INSERT INTO public.syllabus_trees (signature, "option", tree_version, subject, level, board, tree, coverage, model)
VALUES ('f72699cac9c0be5695b8b31003f75069de5f4e785f298408ac105f927b3d204d', 'Decision Mathematics 2', 1, 'Further Mathematics', 'A-Level', 'Edexcel', $t42${"topics":[{"title":"Transportation problems","subtopics":["North-west corner method for an initial feasible solution","Stepping-stone method for an improved solution","Formulating the transportation problem as a linear program"]},{"title":"Allocation (assignment) problems","subtopics":["Cost matrix reduction and the Hungarian algorithm","Formulating the Hungarian algorithm as a linear program"]},{"title":"Flows in networks","subtopics":["Cuts and their capacity","Labelling procedure to augment flow and determine maximum flow","Max-flow min-cut theorem","Multiple sources and sinks; vertices with restricted capacity","Determining optimal flow rate subject to given constraints"]},{"title":"Dynamic programming","subtopics":["Principles of dynamic programming and Bellman's principle of optimality","Stage and state variables; tabulation to solve maximum, minimum, minimax or maximin problems"]},{"title":"Game theory","subtopics":["Two-person zero-sum games and the pay-off matrix","Play-safe strategies and stable solutions (saddle points)","Reducing pay-off matrices using dominance arguments","Optimal mixed strategies via graphical methods (2xn or nx2 games)","Optimal mixed strategies via linear programming / Simplex"]},{"title":"Recurrence relations","subtopics":["Using recurrence relations to model appropriate problems","Solving first and second order linear recurrence relations"]},{"title":"Decision analysis","subtopics":["Constructing and interpreting decision trees","Expected monetary values (EMVs) and utility"]}],"coverage":{"verdict":"grounded","topics_grounded":7,"topics_total":7,"source_url":"https://qualifications.pearson.com"}}$t42$::jsonb, $c43${"verdict":"grounded","topics_grounded":7,"topics_total":7,"source_url":"https://qualifications.pearson.com"}$c43$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
