INSERT INTO public.syllabus_trees (signature, "option", tree_version, subject, level, board, tree, coverage, model)
VALUES ('48aa109631bea58154720c5eae4ca74d4ae03ed2d39fa21106e1e37d78c6fc98', '', 1, 'Mathematics', 'Admissions test', 'TMUA', $t44${"topics":[{"title":"[Paper 1 Knowledge Base] MM1. Algebra and functions","subtopics":["Laws of indices for all rational exponents","Use and manipulation of surds — simplifying expressions, including rationalising the denominator","Quadratic functions and their graphs; the discriminant; completing the square; solving quadratic equations","Simultaneous equations: analytical solution by substitution (e.g. one linear and one quadratic equation)","Solution of linear and quadratic inequalities","Algebraic manipulation of polynomials: expanding/collecting like terms, factorisation and algebraic division, use of the Factor and Remainder Theorems","Functions as many-to-one/one-to-one mappings; familiarity with f(x)=√x (positive square root) and f(x)=|x|"]},{"title":"[Paper 1 Knowledge Base] MM2. Sequences and series","subtopics":["Sequences given by an nth-term formula, and by a simple recurrence relation x(n+1)=f(x(n))","Arithmetic series, including the formula for the sum of the first n natural numbers","Sum of a finite geometric series; sum to infinity of a convergent geometric series, including use of |r|<1","Binomial expansion of (1+x)^n and (a+f(x))^n for positive integer n; notation n! and (n choose r)"]},{"title":"[Paper 1 Knowledge Base] MM3. Coordinate geometry in the (x,y)-plane","subtopics":["Equation of a straight line (point-slope and general forms); conditions for parallel/perpendicular lines; finding equations of lines","Coordinate geometry of the circle, using standard-form and general-form circle equations","Circle properties: chord bisector, tangent-radius perpendicularity, angle at centre vs circumference, angle in a semicircle, angles in the same segment, cyclic quadrilateral angle sum, tangent-chord (alternate segment) angle"]},{"title":"[Paper 1 Knowledge Base] MM4. Trigonometry","subtopics":["The sine and cosine rules; area of a triangle as ½ab sin C; the ambiguous (angle-side-side) case; 2D and 3D problems","Radian measure, including its use for arc length and area of a sector and segment","Exact values of sine, cosine and tangent for 0°, 30°, 45°, 60°, 90°","The sine, cosine and tangent functions: their graphs, symmetries and periodicity","Knowledge and use of tan θ = sin θ/cos θ and sin²θ + cos²θ = 1","Solving simple trigonometric equations in a given interval, using the identities above"]},{"title":"[Paper 1 Knowledge Base] MM5. Exponentials and logarithms","subtopics":["y = a^x and its graph, for simple positive values of a","Laws of logarithms, including the special cases log_a(1/x) = -log_a(x) and log_a(a) = 1 (change of base not required)","Solving equations of the form a^x = b, including those requiring prior algebraic manipulation"]},{"title":"[Paper 1 Knowledge Base] MM6. Differentiation","subtopics":["The derivative of f(x) as the gradient of the tangent at a point; rate of change; second-order derivatives; notation (dy/dx, d²y/dx², f'(x), f''(x))","Differentiation of x^n for rational n and related sums/differences, including expressions needing simplification first","Applications of differentiation: gradients, tangents, normals, stationary points (maxima/minima), strictly increasing/decreasing functions"]},{"title":"[Paper 1 Knowledge Base] MM7. Integration","subtopics":["Definite integration as the area between a curve and an axis, and the distinction between the two","Definite and indefinite integrals of x^n for n rational, n ≠ -1, including expressions needing simplification before integrating","The Fundamental Theorem of Calculus and its significance to integration","Combining integrals with equal or contiguous ranges","Approximating the area under a curve using the trapezium rule; determining over- vs under-estimate","Solving differential equations of the form dy/dx = f(x)"]},{"title":"[Paper 1 Knowledge Base] MM8. Graphs of functions","subtopics":["Recognising and sketching graphs of common functions: lines, quadratics, cubics, trig, log, exponential, square root, modulus","Effect of transformations af(x), f(x)+a, f(x+a), f(ax) on y=f(x); compositions of transformations; notation f(g(x))","How m and c affect the graph of y = mx + c","How a, b and c affect the graph of y = a(x+b)² + c","Using differentiation to determine a graph's shape: finding stationary points and whether increasing/decreasing","Using algebraic techniques to find where a graph meets the coordinate axes; possible numbers of real roots of a general polynomial","Geometric interpretation of algebraic solutions of equations; graph intersections vs solutions of simultaneous equations"]},{"title":"[Paper 1 Knowledge Base] M1. Units","subtopics":["Standard units of mass, length, time, money and other measures; compound units (speed, rates of pay, unit pricing, density, pressure)","Changing freely between related standard units and compound units, in numerical and algebraic contexts"]},{"title":"[Paper 1 Knowledge Base] M2. Number (1)","subtopics":["Ordering positive/negative integers, decimals and fractions; symbols =, ≠, <, >, ≤, ≥","Four operations (add, subtract, multiply, divide) on integers, decimals, fractions and mixed numbers, positive or negative; place value","Prime numbers, factors, multiples, common factors/multiples, HCF, LCM, prime factorisation","Relationships between operations including inverses; cancellation; order/priority of operations (brackets, powers, roots, reciprocals)","Systematic listing strategies (e.g. m ways × n ways = m×n total ways)","Terms square, positive/negative square root, cube and cube root","Index laws to simplify numerical expressions; multiplying/dividing integer, fractional and negative powers","Standard index form (a×10^n, 1≤a<10): interpreting, ordering and calculating","Converting between terminating decimals, percentages and fractions; converting recurring decimals to fractions","Using fractions, decimals and percentages interchangeably in calculations; equivalent fractions","Calculating exactly with fractions, surds and multiples of π; simplifying surds; rationalising denominators","Calculating with upper and lower bounds, and using them in contextual problems"]},{"title":"[Paper 1 Knowledge Base] M2. Number (2)","subtopics":["Rounding numbers/measures to an appropriate degree of accuracy; inequality notation for error intervals due to truncation/rounding","Using approximation to estimate calculations, including expressions involving π or surds"]},{"title":"[Paper 1 Knowledge Base] M3. Ratio and proportion","subtopics":["Scale factors, scale diagrams and maps","Expressing a quantity as a fraction of another, where the fraction is less than or greater than 1","Ratio notation","Dividing a given quantity into two or more parts in a given part:part ratio; expressing division of a quantity as a ratio","Applying ratio to real contexts: conversion, comparison, scaling, mixing, concentrations; multiplicative relationship as ratio or fraction","Understanding and using proportion; relating ratios to fractions and to linear functions","Identifying and working with fractions in ratio problems","Percentage as parts per hundred; percentage of a quantity, comparisons, values over 100%, percentage change including increase/decrease, original value and simple interest","Direct and inverse proportion, including algebraic representations, recognising/interpreting their graphs, and solving problems (including fractional powers)","Comparing lengths, areas and volumes using ratio notation; links to similarity (including trig ratios) and scale factors","Growth and decay problems, including compound interest, and working with general iterative processes"]},{"title":"[Paper 1 Knowledge Base] M4. Algebra (1)","subtopics":["Understanding, using and interpreting algebraic notation (ab, 3y, a², a³, a²b, a/b conventions)","Index laws in algebra for multiplication and division of integer, fractional and negative powers","Substituting numerical values into formulae and expressions, including scientific formulae; vocabulary of expressions/equations/formulae/identities/inequalities/terms/factors","Collecting like terms, multiplying a single term over a bracket, taking out common factors, expanding products of two or more binomials","Factorising quadratic expressions of the form x²+bx+c and ax²+bx+c, including the difference of two squares","Simplifying expressions with sums, products and powers using index laws; simplifying and using the four rules on rational algebraic expressions","Rearranging formulae to change the subject","The difference between an equation and an identity; arguing mathematically that algebraic expressions are equivalent","Working with coordinates in all four quadrants","Identifying/interpreting gradients and intercepts of y=mx+c graphically and algebraically; parallel/perpendicular line pairs; finding a line's equation through two points or a point and gradient","Identifying and interpreting roots, intercepts and turning points of quadratic functions graphically; deducing roots algebraically and turning points by completing the square","Recognising, sketching and interpreting graphs: linear, quadratic, simple cubic, reciprocal y=1/x, exponential y=k^x, and trigonometric functions in degrees"]},{"title":"[Paper 1 Knowledge Base] M4. Algebra (2)","subtopics":["Interpreting graphs (incl. reciprocal and exponential) and non-standard functions in real contexts, including kinematics (distance, speed, acceleration)","Calculating/estimating gradients of graphs and areas under graphs; interpreting results in distance-time, speed-time and financial contexts","Setting up and solving simultaneous equations (linear/linear or linear/quadratic) algebraically and graphically; translating situations into algebraic equations","Solving quadratic equations by factorising, completing the square, and using the quadratic formula; approximate graphical solutions","Solving linear inequalities in one or two variables; representing the solution set on a number line, graph or in words","Generating terms of a sequence using term-to-term or position-to-term rules","Deducing expressions for the nth term of linear or quadratic sequences"]},{"title":"[Paper 1 Knowledge Base] M5. Geometry (1)","subtopics":["Conventional geometric terms and notation: points, lines, line segments, vertices, edges, planes, parallel/perpendicular lines, right angles, subtended angles, polygons and their symmetries","Angle facts at a point, on a straight line, perpendicular lines, opposite angles at a vertex; angle properties of parallel lines, triangles and quadrilaterals; interior/exterior angle sums of polygons","Deriving and applying properties of special quadrilaterals (square, rectangle, parallelogram, trapezium, kite, rhombus) and of triangle types and other plane figures","Congruence criteria for triangles: SSS, SAS, ASA, RHS","Applying angle facts, triangle congruence, similarity and quadrilateral properties to derive results about angles and sides","Identifying, describing and constructing congruent/similar shapes via rotation, reflection, translation, enlargement (incl. fractional/negative scale factors); invariance; translations as 2D vectors","Pythagoras' theorem (a²+b²=c²) in two and three dimensions","Conventional circle terms: centre, radius, chord, diameter, circumference, tangent, arc, sector, segment (incl. minor/major)","Standard circle theorems concerning angles, radii, tangents and chords, and using them to prove related results","Solving geometrical problems on 2-dimensional coordinate axes","Terminology faces, surfaces, edges, vertices for cubes, cuboids, prisms, cylinders, pyramids, cones, spheres and hemispheres","Interpreting plans and elevations of 3-dimensional shapes"]},{"title":"[Paper 1 Knowledge Base] M5. Geometry (2)","subtopics":["Using and interpreting maps and scale drawings; three-figure bearings","Applying formulae for the area of triangles, parallelograms and trapezia, and the volume of cuboids and other right prisms","Circumference/area of a circle and volume of a right circular cylinder formulae; perimeters, areas of composite shapes; surface area/volume of spheres, pyramids, cones and composite solids (sphere/pyramid/cone formulae given if needed)","Calculating arc lengths, angles and areas of sectors of circles","Applying congruence and similarity in simple figures, including relationships between lengths, areas and volumes","Trigonometric ratios sin/cos/tan; applying to angles/lengths in right-angled and general triangles in 2D/3D; exact values for 0°,30°,45°,60°,90°","Addition/subtraction of vectors, scalar multiplication, diagrammatic and column representations; using vectors to construct geometric arguments and proofs"]},{"title":"[Paper 1 Knowledge Base] M6. Statistics","subtopics":["Interpreting/constructing tables, charts and diagrams: two-way/frequency tables, bar/pie charts, pictograms (categorical); vertical line charts (ungrouped discrete); tables/line graphs for time series","Interpreting/constructing diagrams for grouped discrete and continuous data: histograms (equal/unequal class intervals) and cumulative frequency graphs; frequency density","Calculating mean/mode/median/range for ungrouped data; modal class and estimates for grouped data; comparisons via summary values; quartiles and interquartile range","Using/interpreting scatter graphs of bivariate data; correlation (not causation); lines of best fit; interpolation vs extrapolation"]},{"title":"[Paper 1 Knowledge Base] M7. Probability","subtopics":["Analysing the frequency of outcomes of probability experiments using tables and frequency trees","Applying randomness, fairness and equally likely events to calculate expected outcomes of multiple future experiments","Relating relative expected frequencies to theoretical probability, using the 0-to-1 probability scale","The probabilities of an exhaustive set of outcomes, and of a mutually exclusive set of events, sum to one","Enumerating sets and combinations of sets systematically using tables, grids, Venn diagrams and tree diagrams (no formal set notation required)","Constructing theoretical possibility spaces for single and combined equally-likely experiments to calculate theoretical probabilities","Knowing when to add or multiply probabilities; conditional probability via two-way tables/tree/Venn diagrams; independent vs dependent tree diagrams"]},{"title":"[Paper 2 Reasoning] The Logic of Arguments","subtopics":["Mathematical logic: true/false, and/or (inclusive)/not; statement forms 'if A then B', 'A if B', 'A only if B', 'A if and only if B'; the converse and contrapositive of a statement; relationship between the truth of a statement, its converse and its contrapositive (no symbolic notation or formal truth tables required)","The terms necessary and sufficient","The terms for all, for some (meaning for at least one), and there exists","Negating statements that use any of the logical terms above"]},{"title":"[Paper 2 Reasoning] Mathematical Proof","subtopics":["Following, and in simple cases constructing, a direct deductive proof ('Since A, therefore B, therefore C, ..., therefore Z')","Deducing implications from given statements","Making conjectures based on small cases, and justifying those conjectures","Rearranging a sequence of statements into the correct order to give a proof for a statement","Solving problems that require a sophisticated chain of reasoning"]},{"title":"[Paper 2 Reasoning] Identifying Errors in Proofs","subtopics":["Identifying errors in purported proofs","Awareness of common mathematical errors in purported proofs, e.g. wrongly claiming 'if ab=ac then b=c' or 'if sin A = sin B then A = B'"]}],"coverage":{"verdict":"grounded","topics_grounded":21,"topics_total":21,"source_url":"https://uat-wp.s3.eu-west-2.amazonaws.com/wp-content/uploads/2024/05/03165619/TMUA_Content_Specification.pdf"}}$t44$::jsonb, $c45${"verdict":"grounded","topics_grounded":21,"topics_total":21,"source_url":"https://uat-wp.s3.eu-west-2.amazonaws.com/wp-content/uploads/2024/05/03165619/TMUA_Content_Specification.pdf"}$c45$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
ON CONFLICT (signature, "option", tree_version) DO UPDATE SET
  tree = EXCLUDED.tree, coverage = EXCLUDED.coverage, model = EXCLUDED.model, subject = EXCLUDED.subject, level = EXCLUDED.level, board = EXCLUDED.board;

INSERT INTO public.syllabus_trees (signature, "option", tree_version, subject, level, board, tree, coverage, model)
VALUES ('c195ab35496d0e8d64bebb827c19bbe0d0cb950457cc52e5751e8739c3cb48ef', '', 1, 'Science', 'Admissions test', 'ESAT', $t46${"topics":[{"title":"M1. Units","subtopics":["Use standard units of mass, length, time, money and other measures; use compound units such as speed, rates of pay, unit pricing, density and pressure, including decimal quantities where appropriate.","Change freely between related standard units (e.g. time, length, area, volume/capacity, mass) and compound units (e.g. speed, rates of pay, prices, density, pressure) in numerical and algebraic contexts."]},{"title":"M2. Number (1)","subtopics":["Order positive and negative integers, decimals and fractions; understand and use the symbols =, ≠, <, >, ≤, ≥.","Apply the four operations (addition, subtraction, multiplication and division) to integers, decimals, simple fractions and mixed numbers, positive and negative; understand and use place value.","Use the concepts and vocabulary of prime numbers, factors (divisors), multiples, common factors, common multiples, highest common factor, lowest common multiple, and prime factorisation.","Recognise and use relationships between operations, including inverse operations; use cancellation to simplify calculations and expressions; understand and use the convention for priority of operations.","Apply systematic listing strategies.","Use and understand the terms square, positive and negative square root, cube and cube root.","Use index laws to simplify numerical expressions, and for multiplication and division of integer, fractional and negative powers.","Interpret, order and calculate with numbers written in standard index form (standard form).","Convert between terminating decimals, percentages and fractions; convert between recurring decimals and their corresponding fractions.","Use fractions, decimals and percentages interchangeably in calculations; understand equivalent fractions.","Calculate exactly with fractions, surds and multiples of π; simplify surd expressions involving squares and rationalise denominators.","Calculate with upper and lower bounds, and use in contextual problems."]},{"title":"M2. Number (2)","subtopics":["Round numbers and measures to an appropriate degree of accuracy; use inequality notation to specify simple error intervals due to truncation or rounding.","Use approximation to produce estimates of calculations, including expressions involving π or surds."]},{"title":"M3. Ratio and proportion","subtopics":["Understand and use scale factors, scale diagrams and maps.","Express a quantity as a fraction of another, where the fraction is less than 1 or greater than 1.","Understand and use ratio notation.","Divide a given quantity into two (or more) parts in a given part:part ratio; express the division of a quantity into two parts as a ratio.","Apply ratio to real contexts and problems, such as those involving conversion, comparison, scaling, mixing and concentrations; express a multiplicative relationship between two quantities as a ratio or a fraction.","Understand and use proportion; relate ratios to fractions and to linear functions.","Identify and work with fractions in ratio problems.","Define percentage as 'number of parts per hundred'; interpret percentages and percentage changes multiplicatively; solve problems involving percentage change including simple interest.","Understand and use direct and inverse proportion, including algebraic representations; recognise and interpret graphs that illustrate direct and inverse proportion.","Compare lengths, areas and volumes using ratio notation; understand and make links to similarity (including trigonometric ratios) and scale factors.","Set up, solve and interpret the answers in growth and decay problems, including compound interest, and work with general iterative processes."]},{"title":"M4. Algebra (1)","subtopics":["Understand, use and interpret algebraic notation, e.g. ab in place of a×b, 3y in place of y+y+y, a² in place of a×a.","Use index laws in algebra for multiplication and division of integer, fractional, and negative powers.","Substitute numerical values into formulae and expressions, including scientific formulae; understand and use the concepts and vocabulary of expressions, equations, formulae, identities, inequalities, terms and factors.","Collect like terms, multiply a single term over a bracket, take out common factors, and expand products of two or more binomials.","Factorise quadratic expressions of the form x²+bx+c and ax²+bx+c, including the difference of two squares.","Simplify expressions involving sums, products and powers, including the laws of indices; simplify rational expressions by cancelling, or factorising and cancelling; use the four rules on algebraic rational expressions.","Rearrange formulae to change the subject.","Understand the difference between an equation and an identity; argue mathematically to show that algebraic expressions are equivalent.","Work with coordinates in all four quadrants.","Identify and interpret gradients and intercepts of linear functions (y = mx + c) graphically and algebraically; identify pairs of parallel and perpendicular lines; find the equation of a line through two points or through one point with a given gradient.","Identify and interpret roots, intercepts and turning points of quadratic functions graphically; deduce roots algebraically, and turning points by completing the square.","Recognise, sketch and interpret graphs of: linear, quadratic, simple cubic, reciprocal, exponential, and trigonometric functions (with arguments in degrees)."]},{"title":"M4. Algebra (2)","subtopics":["Interpret graphs (including reciprocal and exponential graphs) and graphs of non-standard functions in real contexts to find approximate solutions to problems, such as simple kinematic problems involving distance, speed and acceleration.","Calculate or estimate gradients of graphs and areas under graphs (including quadratic and other non-linear graphs), and interpret results in cases such as distance–time, speed–time and financial graphs.","Set up and solve, both algebraically and graphically, simultaneous equations involving two unknowns, including one linear and one quadratic equation; translate situations into algebraic expressions or formulae.","Solve quadratic equations (including those that require rearrangement) algebraically by factorising, completing the square, and using the quadratic formula; find approximate solutions using a graph.","Solve linear inequalities in one or two variables; represent the solution set on a number line, on a graph, or in words.","Generate terms of a sequence using term-to-term or position-to-term rules.","Deduce expressions to calculate the nth term of linear or quadratic sequences."]},{"title":"M5. Geometry (1)","subtopics":["Use conventional terms and notation: points, lines, line segments, vertices, edges, planes, parallel lines, perpendicular lines, right angles, subtended angles, polygons, regular polygons and polygons with reflection and/or rotational symmetries.","Recall and use the properties of angles at a point, angles on a straight line, perpendicular lines and opposite angles at a vertex; understand and use angle properties of parallel lines, intersecting lines, triangles and quadrilaterals; calculate the sum of interior and exterior angles of polygons.","Derive and apply the properties and definitions of special types of quadrilaterals, including square, rectangle, parallelogram, trapezium, kite and rhombus, and of various types of triangle and other plane figures.","Understand and use the basic congruence criteria for triangles (SSS, SAS, ASA, RHS).","Apply angle facts, triangle congruence, similarity, and properties of quadrilaterals to results about angles and sides.","Identify, describe and construct congruent and similar shapes, including on coordinate axes, by considering rotation, reflection, translation and enlargement; describe translations as 2-dimensional vectors.","Know and use the formula for Pythagoras' theorem: a²+b²=c², in both 2 and 3 dimensions.","Identify and use conventional circle terms: centre, radius, chord, diameter, circumference, tangent, arc, sector and segment.","Apply the standard circle theorems concerning angles, radii, tangents and chords, and use them to prove related results.","Solve geometrical problems on 2-dimensional coordinate axes.","Know the terminology faces, surfaces, edges and vertices when applied to cubes, cuboids, prisms, cylinders, pyramids, cones, spheres and hemispheres.","Interpret plans and elevations of 3-dimensional shapes."]},{"title":"M5. Geometry (2)","subtopics":["Use and interpret maps and scale drawings; understand and use three-figure bearings.","Know and apply formulae to calculate the area of triangles, parallelograms, trapezia, and the volume of cuboids and other right prisms.","Know the formulae for circumference and area of a circle and volume of a right circular cylinder; use formulae to calculate perimeters, areas and volumes of composite shapes and solids.","Calculate arc lengths, angles and areas of sectors of circles.","Apply the concepts of congruence and similarity in simple figures, including the relationships between lengths, areas and volumes.","Know and use the trigonometric ratios (sin, cos, tan) to find angles and lengths in right-angled triangles and, where possible, general triangles in 2 and 3 dimensions; know exact trigonometric values for standard angles.","Apply addition and subtraction of vectors, multiplication of vectors by a scalar, and diagrammatic and column representations of vectors; use vectors to construct geometric arguments and proofs."]},{"title":"M6. Statistics","subtopics":["Interpret and construct tables, charts and diagrams, including two-way tables, frequency tables, bar charts, pie charts, pictograms, vertical line charts, and tables/line graphs for time series data; know the appropriate use of each representation.","Interpret and construct diagrams for grouped discrete and continuous data: histograms with equal and unequal class intervals, and cumulative frequency graphs; understand and use the term frequency density.","Calculate the mean, mode, median and range for ungrouped and grouped data; describe a population using statistics; compare data sets using like-for-like summary values, including quartiles and interquartile range.","Use and interpret scatter graphs of bivariate data; recognise correlation and know it does not indicate causation; draw estimated lines of best fit; interpolate and extrapolate apparent trends."]},{"title":"M7. Probability","subtopics":["Analyse the frequency of outcomes of probability experiments using tables and frequency trees.","Apply ideas of randomness, fairness and equally likely events to calculate expected outcomes of multiple future experiments.","Relate relative expected frequencies to theoretical probability, using appropriate language and the '0 to 1' probability scale.","Apply the property that the probabilities of an exhaustive set of outcomes, or of an exhaustive set of mutually exclusive events, sum to one.","Enumerate sets and combinations of sets systematically, using tables, grids, Venn diagrams and tree diagrams.","Construct theoretical possibility spaces for single and combined experiments with equally likely outcomes, and use these to calculate theoretical probabilities.","Know when to add or multiply two probabilities, and understand conditional probability, including its representation using expected frequencies, two-way tables, tree diagrams and Venn diagrams."]}],"coverage":{"verdict":"grounded","topics_grounded":10,"topics_total":10,"source_url":"https://uat-wp.s3.eu-west-2.amazonaws.com/wp-content/uploads/2024/05/03165424/ESAT_Content_Specification.pdf"},"optionalUnits":["Biology","Chemistry","Physics","Mathematics 2"]}$t46$::jsonb, $c47${"verdict":"grounded","topics_grounded":10,"topics_total":10,"source_url":"https://uat-wp.s3.eu-west-2.amazonaws.com/wp-content/uploads/2024/05/03165424/ESAT_Content_Specification.pdf"}$c47$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
