  tree = EXCLUDED.tree, coverage = EXCLUDED.coverage, model = EXCLUDED.model, subject = EXCLUDED.subject, level = EXCLUDED.level, board = EXCLUDED.board;

INSERT INTO public.syllabus_trees (signature, "option", tree_version, subject, level, board, tree, coverage, model)
VALUES ('c195ab35496d0e8d64bebb827c19bbe0d0cb950457cc52e5751e8739c3cb48ef', 'Physics', 1, 'Science', 'Admissions test', 'ESAT', $t52${"topics":[{"title":"P1. Electricity","subtopics":["Electrostatics: know and understand that insulators can be charged by friction, caused by gain or loss of electrons; know that like charges repel and unlike charges attract; understand applications and hazards, including the role of earthing.","Electric circuits: know and recognise basic circuit symbols and diagrams; understand ac vs dc, conductors vs insulators; know and apply current=charge/time, resistance=voltage/current, voltage=energy/charge, power=current×voltage, energy transfer=power×time; recall V–I graphs for a fixed resistor and filament lamp; know properties of NTC thermistors, LDRs and ideal diodes; understand series/parallel circuit rules and resistance combinations."]},{"title":"P2. Magnetism","subtopics":["Properties of magnets: know and use the terms north pole, south pole, attraction and repulsion; know the magnetic field pattern around a bar magnet; understand the difference between soft and hard magnetic materials; qualitatively understand induced magnetism.","Magnetic field due to an electric current: know and understand the magnetic effect of a current; know the magnetic field patterns around current-carrying wires and coils/solenoids; know factors affecting magnetic field strength; understand the difference between permanent magnets and electromagnets.","The motor effect: know that a current-carrying wire in a magnetic field can experience a force; know the factors affecting the direction (left-hand rule) and magnitude of the force; know and apply F=BIL; understand the construction and operation of a dc motor; understand applications of electromagnets.","Electromagnetic induction: know and understand that a voltage is induced when a wire cuts magnetic field lines or when a magnetic field changes; know factors affecting the magnitude and direction of an induced voltage; understand the operation of an ac generator and interpret its output voltage graph; understand applications of electromagnetic induction.","Transformers: know and understand step-up and step-down transformers; know and use the voltage-turns ratio Vp/Vs = np/ns and VpIp = VsIs; understand power transmission, including calculating losses and the need for high voltage."]},{"title":"P3. Mechanics","subtopics":["Kinematics: know and understand the difference between scalar and vector quantities, distance and displacement, speed and velocity; know and apply speed=distance/time, velocity=change in displacement/time, acceleration=change in velocity/time, average speed=total distance/time; interpret distance–time, displacement–time, speed–time and velocity–time graphs including gradients and areas; know and apply v²−u²=2as.","Forces: understand different types of force (weight, normal contact, drag/air resistance, friction, magnetic, electrostatic, thrust, upthrust, lift, tension); know factors affecting their magnitude and direction; draw and interpret force diagrams; qualitatively understand resultant force with one-dimensional calculations.","Force and extension: interpret force–extension graphs; understand elastic and inelastic extension and elastic limits; know and apply Hooke's law (F=kx) and the limit of proportionality; understand energy stored in a stretched spring, E=½Fx=½kx².","Newton's laws: know and understand Newton's first law (a body remains at rest or in uniform motion unless acted on by a resultant external force); understand mass as inertia; know and understand Newton's second law (force=mass×acceleration); know and understand Newton's third law (equal and opposite force pairs).","Mass and weight: know and understand the difference between mass and weight; know and apply gravitational field strength g ≈ 10 N/kg on Earth and w=mg; understand free-fall acceleration, factors affecting air resistance, and terminal velocity.","Momentum: know and apply momentum=mass×velocity, p=mv; know and use the law of conservation of momentum in one-dimensional calculations; know and apply force=rate of change of momentum.","Energy: know and apply work=force×distance moved and understand work done as energy transfer; know and apply gravitational potential energy=mgh and kinetic energy=½mv²; know and apply power=energy transfer/time; use the law of conservation of energy; understand useful/wasted energy and know and apply percentage efficiency=(useful output/total input)×100."]},{"title":"P4. Thermal physics","subtopics":["Conduction: know and understand thermal conductors and insulators, with examples; know and be able to apply factors affecting rate of conduction.","Convection: understand and apply the effect of temperature on density of fluid, and fluid flow caused by differences in density.","Thermal radiation: understand thermal radiation as electromagnetic waves in the infrared region; know and apply absorption and emission of radiation and factors affecting their rate.","Heat capacity: understand the effect of energy transferred to or from an object on its temperature; know and apply specific heat capacity = thermal energy/(mass×temperature change)."]},{"title":"P5. Matter","subtopics":["States of matter: know the characteristic properties of solids, liquids and gases; know and apply particle models; explain properties in terms of particle motion and forces/distances between particles.","Ideal gases: explain pressure and temperature in terms of particle behaviour; understand and apply the effect of pressure on gas volume at constant temperature, PV=constant.","State changes: understand melting point and boiling point; know and understand latent heat of fusion and vaporisation; know and apply specific latent heat calculations.","Density: know and apply density=mass/volume, ρ=m/V; understand experimental determination of densities; compare densities of solids, liquids and gases.","Pressure: know and apply pressure=force/area and hydrostatic pressure=hρg."]},{"title":"P6. Waves","subtopics":["Wave properties: understand transfer of energy without net movement of matter; know and understand transverse and longitudinal waves and the terms peak, trough, compression, rarefaction; recall examples of waves; know and use amplitude, wavelength, frequency and period; know and apply frequency=1/period and wave speed=frequency×wavelength.","Wave behaviour: know and understand reflection and refraction at a boundary and their effect on speed, frequency, wavelength and direction; understand the analogy of reflection/refraction of light with water waves; know and understand the Doppler effect.","Optics: draw and interpret ray diagrams for reflection in plane mirrors and refraction at a planar boundary; know and apply angle of incidence=angle of reflection; interpret angle of incidence and refraction and the effect of refraction on wave direction and speed.","Sound waves: understand production of sound by a vibrating source and the need for a medium; understand loudness/amplitude and pitch/frequency relationships; know that sound is a longitudinal wave; understand echoes; recall the human hearing range (20 Hz–20 kHz); know and understand ultrasound and its uses (sonar, medical scanning).","Electromagnetic spectrum: know and understand the nature and properties of electromagnetic waves (transverse, travel at speed of light in vacuum); recall the component parts of the spectrum (radio, microwave, IR, visible, UV, X-ray, gamma); understand distinction by wavelength/frequency and recall their order; understand applications and hazards of each part."]},{"title":"P7. Radioactivity","subtopics":["Atomic structure: understand the atom in terms of protons, neutrons and electrons and the nuclear model; know relative charges and masses; understand and use atomic number and mass number; know the terms isotope and nuclide, and use nuclide notation; understand that ionisation is caused by gain/loss of electrons.","Radioactive decay: know and understand that emissions arise from an unstable nucleus and are random; know and understand the differences between alpha, beta and gamma emission and their nature; be able to use and interpret nuclear equations; know the effect of decay on atomic number and mass number.","Ionising radiation: know the relative penetrating and ionising abilities of alpha, beta and gamma radiation; understand qualitatively their deflection in electric or magnetic fields; know and appreciate the existence of background radiation; understand the applications and hazards of ionising radiation.","Half-life: be able to interpret graphical representations of radioactive decay (including decay products); understand the meaning of the term half-life; understand and be able to apply half-life calculations."]}],"coverage":{"verdict":"grounded","topics_grounded":7,"topics_total":7,"source_url":"https://uat-wp.s3.eu-west-2.amazonaws.com/wp-content/uploads/2024/05/03165424/ESAT_Content_Specification.pdf"}}$t52$::jsonb, $c53${"verdict":"grounded","topics_grounded":7,"topics_total":7,"source_url":"https://uat-wp.s3.eu-west-2.amazonaws.com/wp-content/uploads/2024/05/03165424/ESAT_Content_Specification.pdf"}$c53$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
