INSERT INTO public.syllabus_trees (signature, "option", tree_version, subject, level, board, tree, coverage, model)
VALUES ('c195ab35496d0e8d64bebb827c19bbe0d0cb950457cc52e5751e8739c3cb48ef', 'Mathematics 2', 1, 'Science', 'Admissions test', 'ESAT', $t54${"topics":[{"title":"MM1. Algebra and functions","subtopics":["Laws of indices for all rational exponents.","Use and manipulation of surds, including simplifying expressions containing surds and rationalising the denominator.","Quadratic functions and their graphs; the discriminant of a quadratic function; completing the square; solution of quadratic equations.","Simultaneous equations: analytical solution by substitution, e.g. of one linear and one quadratic equation.","Solution of linear and quadratic inequalities.","Algebraic manipulation of polynomials, including expanding brackets and collecting like terms; factorisation and simple algebraic division (by a linear or quadratic polynomial); use of the Factor Theorem and the Remainder Theorem.","Qualitative understanding that a function is a many-to-one (or sometimes one-to-one) mapping; familiarity with properties of common functions, including f(x)=√x and f(x)=|x|."]},{"title":"MM2. Sequences and series","subtopics":["Sequences, including those given by a formula for the nth term and those generated by a simple recurrence relation of the form x(n+1)=f(xn).","Arithmetic series, including the formula for the sum of the first n natural numbers.","The sum of a finite geometric series; the sum to infinity of a convergent geometric series, including the use of |r|<1.","Binomial expansion of (1+x)^n for positive integer n, and for expressions of the form (a+f(x))^n for positive integer n and simple f(x); the notations n! and (n choose r)."]},{"title":"MM3. Coordinate geometry in the (x,y)-plane","subtopics":["Equation of a straight line, including y−y1=m(x−x1) and ax+by+c=0; conditions for two straight lines to be parallel or perpendicular; finding equations of straight lines given information in various forms.","Coordinate geometry of the circle, using the equation of a circle in the forms (x−a)²+(y−b)²=r² and x²+y²+cx+dy+e=0.","Use of circle properties: perpendicular from centre bisects a chord; tangent perpendicular to radius; angle at centre is twice angle at circumference; angle in a semicircle is a right angle; angles in the same segment are equal; opposite angles in a cyclic quadrilateral sum to 180°; angle between tangent and chord equals angle in alternate segment."]},{"title":"MM4. Trigonometry","subtopics":["The sine and cosine rules, and the area of a triangle in the form ½ab sinC, including the ambiguous case of the sine rule; problems might be set in 2 or 3 dimensions.","Radian measure, including use for arc length and area of sector and segment.","The values of sine, cosine and tangent for the angles 0°, 30°, 45°, 60°, 90°.","The sine, cosine and tangent functions; their graphs, symmetries, and periodicity.","Knowledge and use of the equations tanθ=sinθ/cosθ and sin²θ+cos²θ=1.","Solution of simple trigonometric equations in a given interval, which may involve the use of the identities in MM4.5."]},{"title":"MM5. Exponentials and logarithms","subtopics":["y=a^x and its graph, for simple positive values of a.","Laws of logarithms, including the special cases loga(1/x)=−logax and logaa=1; questions requiring knowledge of the change of base formula will not be set.","The solution of equations of the form a^x=b, and equations which can be reduced to this form, including those that need prior algebraic manipulation."]},{"title":"MM6. Differentiation","subtopics":["The derivative of f(x) as the gradient of the tangent to the graph y=f(x) at a point; interpretation as a rate of change; second-order derivatives; knowledge of notation dy/dx, d²y/dx², f'(x), f''(x); differentiation from first principles is excluded.","Differentiation of x^n for rational n, and related sums and differences, which might require simplification before differentiating.","Applications of differentiation to gradients, tangents, normals, stationary points (maxima and minima only), strictly increasing/decreasing functions; points of inflexion are not examined, though a qualitative understanding is expected."]},{"title":"MM7. Integration","subtopics":["Definite integration as related to the 'area between a curve and an axis'; the difference between finding a definite integral and finding the area between a curve and an axis is expected to be understood.","Finding definite and indefinite integrals of x^n for n rational, n≠−1, and related sums and differences, including expressions requiring simplification prior to integrating.","An understanding of the Fundamental Theorem of Calculus and its significance to integration.","Combining integrals with either equal or contiguous ranges.","Approximation of the area under a curve using the trapezium rule; determination of whether this constitutes an overestimate or underestimate.","Solving differential equations of the form dy/dx=f(x)."]},{"title":"MM8. Graphs of functions","subtopics":["Recognise and be able to sketch the graphs of common functions that appear in this specification: lines, quadratics, cubics, trigonometric functions, logarithmic functions, exponential functions, square roots, and the modulus function.","Knowledge of the effect of simple transformations on the graph of y=f(x): y=af(x), y=f(x)+a, y=f(x+a), y=f(ax); compositions of these transformations; knowledge and use of the notation f(g(x)).","Understand how altering the values of m and c affects the graph of y=mx+c.","Understand how altering the values of a, b and c in y=a(x+b)²+c affects the corresponding graph.","Use differentiation to help determine the shape of the graph of a given function, including finding stationary points (excluding inflexions) and when the graph is increasing or decreasing.","Use algebraic techniques to determine where the graph of a function intersects the coordinate axes; appreciate the possible numbers of real roots that a general polynomial can possess.","Geometric interpretation of algebraic solutions of equations; relationship between the intersections of two graphs and the solutions of the corresponding simultaneous equations."]}],"coverage":{"verdict":"grounded","topics_grounded":8,"topics_total":8,"source_url":"https://uat-wp.s3.eu-west-2.amazonaws.com/wp-content/uploads/2024/05/03165424/ESAT_Content_Specification.pdf"}}$t54$::jsonb, $c55${"verdict":"grounded","topics_grounded":8,"topics_total":8,"source_url":"https://uat-wp.s3.eu-west-2.amazonaws.com/wp-content/uploads/2024/05/03165424/ESAT_Content_Specification.pdf"}$c55$::jsonb, 'claude-sonnet-5 (manual spec extraction, human-verified, not AI-generated)')
